-- TomoModForever 1.4.1: TMF's own action bars, Forever ornate skin, shine
-- and halo animations, boat, zeppelin and airship routes, zone levels, dungeon codex
-- entrances and raids, quick keybind mode, quest reward tooltips (Core/WhatsNew.lua).
-- No "+", guillemets or bullets in these strings: the font may not carry them.

TomoMod_RegisterLocale("enUS", {
    ["wn_141_bars"] = "New - TMF action bars (expert mode): the game's buttons move into TMF's own bars. Pick each bar's size, button count, buttons per row and spacing, and drag them anywhere in Layout mode. Spells, macros, keybinds, pet, stance and totem bars all keep working. Off by default: Action bars, TMF bars. On the first turn-on the bars stay where they were. In simple mode the game's bars only keep the skin.",
    ["wn_141_sets"] = "New - Sets of bars and attached bars: bars in a set share size, button count, rows and spacing, so a change on bar 1 also reaches bars 2 and 3. Drop a bar against another one in Layout mode and it sticks to it: it follows its moves and size changes, and joins its set. Bars Blizzard had stacked start attached.",
    ["wn_141_ornate"] = "New - Forever ornate skin for the action buttons: bronze and gold frame with a soft golden halo under the mouse. A golden gleam also crosses an icon when a long cooldown is ready again (can be turned off). Both follow the animation setting.",
    ["wn_141_travel"] = "New - Map: every boat, zeppelin and airship of WoW Forever, from the game's own tables, including Stormwind to Darkshore, Steamwheedle Port to Powderfuse Port (Riverglades), the Menethil, Southshore and Auberdine boat and the airships to Zephras Isle. Hover a dock to see where it goes, in your language. Zone levels on the map now also cover Zephras Isle (1-12), the Riverglades (35-45) and Mount Hyjal (60).",
    ["wn_141_codex"] = "New - Dungeon codex: entrances now come from the game's own tables, so most dungeons go from an approximate point to the real entrance, and Krol'dok Stronghold, Blackmaw Hold and Shaper's Terrace finally have theirs. The 8 raids join the codex: Molten Core, Blackwing Lair, Onyxia's Lair, Zul'Gurub, both Ahn'Qiraj, and Forever's Hyjal Summit and Barrow Deeps (open on 9 December). /codex compare shows, in game, the gap between each position and the game's entrance. The Stockade is now level 24-32.",
    ["wn_141_dialogue"] = "Fixed - Quest dialogue: reward tooltips no longer cover the quest text and the other reward. They open beside the dialogue window, level with the hovered reward, on the right when the screen has room, on the left otherwise.",
    ["wn_141_kb"] = "Changed - /kb now opens the quick keybind mode: hover a button and press a key. Also a Keybinds button in Action bars.",
})
TomoMod_RegisterLocale("frFR", {
    ["wn_141_bars"] = "Nouveau - Barres d'action TMF (mode expert) : les boutons du jeu passent dans les barres de TMF. Choisis pour chaque barre sa taille, son nombre de boutons, les boutons par ligne et l'espacement, et glisse-les où tu veux en mode Disposition. Sorts, macros, raccourcis, familier, postures et totems fonctionnent comme avant. Désactivé par défaut : Barres d'action, Barres TMF. À la première activation, les barres restent à leur place. En mode simple, les barres du jeu gardent seulement l'habillage.",
    ["wn_141_sets"] = "Nouveau - Ensembles de barres et barres collées : les barres d'un ensemble partagent taille, nombre de boutons, lignes et espacement, donc un changement sur la barre 1 touche aussi les barres 2 et 3. Lâche une barre contre une autre en mode Disposition et elle s'y colle : elle suit ses déplacements et ses changements de taille, et rejoint son ensemble. Les barres que Blizzard avait empilées démarrent collées.",
    ["wn_141_ornate"] = "Nouveau - Habillage Forever orné pour les boutons d'action : cadre bronze et or avec un léger halo doré au survol. Un reflet doré traverse aussi l'icône quand une longue recharge est de nouveau prête (désactivable). Les deux suivent le réglage des animations.",
    ["wn_141_travel"] = "Nouveau - Carte : tous les bateaux, zeppelins et dirigeables de WoW Forever, tirés des tables du jeu, dont Hurlevent - Sombrivage, Port Steamwheedle - Port Powderfuse (Riverglades), le bateau Menethil - Austrivage - Auberdine et les dirigeables vers l'Île de Zephras. Survole un quai pour voir où il mène, dans ta langue. Les niveaux des zones sur la carte couvrent aussi l'Île de Zephras (1-12), les Riverglades (35-45) et le Mont Hyjal (60).",
    ["wn_141_codex"] = "Nouveau - Codex des donjons : les entrées viennent maintenant des tables du jeu, la plupart des donjons passent d'un point approximatif à la vraie entrée, et le Bastion de Krol'dok, le Repaire des Noiregueules et la Terrasse du Façonneur ont enfin la leur. Les 8 raids rejoignent le codex : Cœur du Magma, Repaire de l'Aile noire, Repaire d'Onyxia, Zul'Gurub, les deux Ahn'Qiraj, et le Sommet d'Hyjal et Barrow Deeps de Forever (ouverts le 9 décembre). /codex compare montre en jeu l'écart entre chaque position et l'entrée du jeu. La Prison passe aux niveaux 24-32.",
    ["wn_141_dialogue"] = "Corrigé - Dialogues de quête : les infobulles des récompenses ne recouvrent plus le texte de la quête ni l'autre récompense. Elles s'ouvrent à côté de la fenêtre de dialogue, à hauteur de la récompense survolée, à droite si l'écran a la place, à gauche sinon.",
    ["wn_141_kb"] = "Modifié - /kb ouvre maintenant le mode raccourcis rapide : survole un bouton et appuie sur une touche. Aussi un bouton Raccourcis clavier dans Barres d'action.",
})
TomoMod_RegisterLocale("deDE", {
    ["wn_141_bars"] = "Neu - TMF-Aktionsleisten (Expertenmodus): Die Tasten des Spiels wandern in eigene TMF-Leisten. Wähle für jede Leiste Größe, Anzahl der Tasten, Tasten pro Reihe und Abstand und ziehe sie im Layout-Modus an jede Stelle. Zauber, Makros, Tastenbelegungen, Begleiter-, Haltungs- und Totemleiste funktionieren weiter. Standardmäßig aus: Aktionsleisten, TMF-Leisten. Beim ersten Einschalten bleiben die Leisten an ihrem Platz. Im einfachen Modus behalten die Spielleisten nur den Skin.",
    ["wn_141_sets"] = "Neu - Leistengruppen und angedockte Leisten: Leisten einer Gruppe teilen Größe, Tastenanzahl, Reihen und Abstand, eine Änderung an Leiste 1 gilt also auch für Leiste 2 und 3. Lass eine Leiste im Layout-Modus an einer anderen los und sie dockt an: Sie folgt deren Bewegungen und Größe und tritt ihrer Gruppe bei. Von Blizzard gestapelte Leisten starten angedockt.",
    ["wn_141_ornate"] = "Neu - Skin Forever verziert für die Aktionstasten: Rahmen in Bronze und Gold mit sanftem goldenem Schein unter der Maus. Ein goldener Glanz zieht außerdem über ein Symbol, wenn eine lange Abklingzeit vorbei ist (abschaltbar). Beides folgt der Animationseinstellung.",
    ["wn_141_travel"] = "Neu - Karte: alle Schiffe, Zeppeline und Luftschiffe von WoW Forever aus den Tabellen des Spiels, darunter Sturmwind - Dunkelküste, Hafen Dampfdruck - Hafen Powderfuse (Riverglades), das Schiff Menethil - Süderstade - Auberdine und die Luftschiffe zur Insel Zephras. Über einen Anleger fahren zeigt das Ziel in deiner Sprache. Die Zonenstufen auf der Karte decken jetzt auch die Insel Zephras (1-12), die Riverglades (35-45) und den Berg Hyjal (60) ab.",
    ["wn_141_codex"] = "Neu - Dungeon-Kodex: Die Eingänge stammen jetzt aus den Tabellen des Spiels, die meisten Dungeons haben statt eines ungefähren Punkts den echten Eingang, und Krol'dok-Festung, Schwarzschlund-Feste und Terrasse des Formers haben endlich ihren. Die 8 Schlachtzüge kommen dazu: Geschmolzener Kern, Pechschwingenhort, Onyxias Hort, Zul'Gurub, beide Ahn'Qiraj sowie Forevers Hyjalgipfel und Barrow Deeps (ab 9. Dezember). /codex compare zeigt im Spiel den Abstand jeder Position zum Eingang des Spiels. Das Verlies ist jetzt Stufe 24-32.",
    ["wn_141_dialogue"] = "Behoben - Questdialog: Die Tooltips der Belohnungen überdecken nicht mehr den Questtext und die andere Belohnung. Sie öffnen sich neben dem Dialogfenster, auf Höhe der Belohnung unter der Maus, rechts wenn der Bildschirm Platz hat, sonst links.",
    ["wn_141_kb"] = "Geändert - /kb öffnet jetzt den Schnellbelegungsmodus: über eine Taste fahren und eine Taste drücken. Dazu ein Knopf Tastenbelegung in Aktionsleisten.",
})
TomoMod_RegisterLocale("esES", {
    ["wn_141_bars"] = "Nuevo - Barras de acción de TMF (modo experto): los botones del juego pasan a barras propias de TMF. Elige para cada barra su tamaño, número de botones, botones por fila y espaciado, y arrástralas donde quieras en el modo Disposición. Hechizos, macros, atajos, barras de mascota, actitud y tótems siguen funcionando. Desactivado por defecto: Barras de acción, Barras TMF. Al activarlo por primera vez, las barras se quedan en su sitio. En modo simple, las barras del juego solo conservan la apariencia.",
    ["wn_141_sets"] = "Nuevo - Conjuntos de barras y barras pegadas: las barras de un conjunto comparten tamaño, número de botones, filas y espaciado, así que un cambio en la barra 1 llega también a las barras 2 y 3. Suelta una barra contra otra en el modo Disposición y se pega a ella: sigue sus movimientos y cambios de tamaño, y se une a su conjunto. Las barras que Blizzard tenía apiladas empiezan pegadas.",
    ["wn_141_ornate"] = "Nuevo - Apariencia Forever ornamentada para los botones de acción: marco de bronce y oro con un suave halo dorado al pasar el ratón. Un destello dorado cruza además el icono cuando un tiempo de reutilización largo vuelve a estar listo (se puede desactivar). Ambos siguen el ajuste de animaciones.",
    ["wn_141_travel"] = "Nuevo - Mapa: todos los barcos, zepelines y dirigibles de WoW Forever, sacados de las tablas del juego, entre ellos Ventormenta - Costa Oscura, Puerto Bonvapor - Puerto Powderfuse (Riverglades), el barco Menethil - Costasur - Auberdine y los dirigibles a la Isla de Zephras. Pasa el ratón por un muelle para ver adónde lleva, en tu idioma. Los niveles de zona del mapa cubren también la Isla de Zephras (1-12), las Riverglades (35-45) y el Monte Hyjal (60).",
    ["wn_141_codex"] = "Nuevo - Códice de mazmorras: las entradas vienen ahora de las tablas del juego, la mayoría de mazmorras pasan de un punto aproximado a la entrada real, y la Fortaleza de Krol'dok, el Bastión Fauce Negra y la Terraza del Modelador por fin tienen la suya. Llegan las 8 bandas: Núcleo de Magma, Guarida Alanegra, Guarida de Onyxia, Zul'Gurub, los dos Ahn'Qiraj, y la Cima Hyjal y Barrow Deeps de Forever (abren el 9 de diciembre). /codex compare muestra en el juego la distancia entre cada posición y la entrada del juego. Las Mazmorras pasan a nivel 24-32.",
    ["wn_141_dialogue"] = "Corregido - Diálogo de misión: las descripciones de las recompensas ya no tapan el texto de la misión ni la otra recompensa. Se abren junto a la ventana de diálogo, a la altura de la recompensa bajo el ratón, a la derecha si la pantalla tiene sitio, si no a la izquierda.",
    ["wn_141_kb"] = "Cambiado - /kb abre ahora el modo de atajos rápidos: pasa el ratón por un botón y pulsa una tecla. También un botón Atajos de teclado en Barras de acción.",
})
TomoMod_RegisterLocale("itIT", {
    ["wn_141_bars"] = "Novità - Barre delle azioni di TMF (modalità esperto): i pulsanti del gioco passano in barre proprie di TMF. Scegli per ogni barra dimensione, numero di pulsanti, pulsanti per riga e spaziatura, e trascinale dove vuoi in modalità Disposizione. Incantesimi, macro, tasti rapidi, barre del famiglio, delle posture e dei totem continuano a funzionare. Disattivato di base: Barre delle azioni, Barre TMF. Alla prima attivazione le barre restano al loro posto. In modalità semplice le barre del gioco mantengono solo l'aspetto.",
    ["wn_141_sets"] = "Novità - Insiemi di barre e barre agganciate: le barre di un insieme condividono dimensione, numero di pulsanti, righe e spaziatura, quindi una modifica alla barra 1 vale anche per le barre 2 e 3. Lascia una barra contro un'altra in modalità Disposizione e vi si aggancia: ne segue spostamenti e cambi di dimensione e si unisce al suo insieme. Le barre che Blizzard aveva impilato partono agganciate.",
    ["wn_141_ornate"] = "Novità - Aspetto Forever ornato per i pulsanti d'azione: cornice in bronzo e oro con un leggero alone dorato al passaggio del mouse. Un riflesso dorato attraversa anche l'icona quando una lunga ricarica è di nuovo pronta (disattivabile). Entrambi seguono l'impostazione delle animazioni.",
    ["wn_141_travel"] = "Novità - Mappa: tutte le navi, gli zeppelin e le aeronavi di WoW Forever, prese dalle tabelle del gioco, tra cui Roccavento - Rivafosca, Porto Spargifumo - Porto Powderfuse (Riverglades), la nave Menethil - Riva del Sud - Auberdine e le aeronavi per l'Isola di Zephras. Passa il mouse su un molo per vedere dove porta, nella tua lingua. I livelli delle zone sulla mappa coprono anche l'Isola di Zephras (1-12), le Riverglades (35-45) e il Monte Hyjal (60).",
    ["wn_141_codex"] = "Novità - Codice delle spedizioni: gli ingressi ora vengono dalle tabelle del gioco, la maggior parte delle spedizioni passa da un punto approssimativo all'ingresso vero, e la Roccaforte di Krol'dok, il Rifugio Fauci Nere e la Terrazza del Plasmatore hanno finalmente il loro. Arrivano le 8 incursioni: Nucleo Ardente, Fortezza dell'Ala Nera, Antro di Onyxia, Zul'Gurub, i due Ahn'Qiraj, e la Vetta di Hyjal e Barrow Deeps di Forever (aprono il 9 dicembre). /codex compare mostra in gioco la distanza tra ogni posizione e l'ingresso del gioco. La Prigione passa ai livelli 24-32.",
    ["wn_141_dialogue"] = "Corretto - Dialogo delle missioni: i tooltip delle ricompense non coprono più il testo della missione né l'altra ricompensa. Si aprono accanto alla finestra di dialogo, all'altezza della ricompensa sotto il mouse, a destra se lo schermo ha spazio, altrimenti a sinistra.",
    ["wn_141_kb"] = "Modificato - /kb ora apre la modalità tasti rapidi: passa il mouse su un pulsante e premi un tasto. Anche un pulsante Tasti rapidi in Barre delle azioni.",
})
TomoMod_RegisterLocale("ptBR", {
    ["wn_141_bars"] = "Novo - Barras de ação do TMF (modo especialista): os botões do jogo passam para barras próprias do TMF. Escolha para cada barra o tamanho, o número de botões, botões por linha e espaçamento, e arraste-as para onde quiser no modo Disposição. Feitiços, macros, atalhos, barras do ajudante, de postura e de totens continuam funcionando. Desativado por padrão: Barras de ação, Barras TMF. Na primeira ativação, as barras ficam onde estavam. No modo simples, as barras do jogo só mantêm a aparência.",
    ["wn_141_sets"] = "Novo - Conjuntos de barras e barras grudadas: as barras de um conjunto compartilham tamanho, número de botões, linhas e espaçamento, então uma mudança na barra 1 também chega às barras 2 e 3. Solte uma barra contra outra no modo Disposição e ela gruda: segue os movimentos e mudanças de tamanho da outra e entra no conjunto dela. As barras que a Blizzard tinha empilhado começam grudadas.",
    ["wn_141_ornate"] = "Novo - Aparência Forever ornamentada para os botões de ação: moldura de bronze e ouro com um leve halo dourado sob o mouse. Um brilho dourado também cruza o ícone quando uma recarga longa fica pronta de novo (pode ser desligado). Os dois seguem a configuração de animações.",
    ["wn_141_travel"] = "Novo - Mapa: todos os barcos, zepelins e dirigíveis do WoW Forever, tirados das tabelas do jogo, entre eles Ventobravo - Costa Negra, Porto Vaportela - Porto Powderfuse (Riverglades), o barco Menethil - Costa Sul - Auberdine e os dirigíveis para a Ilha de Zephras. Passe o mouse sobre um cais para ver para onde ele leva, no seu idioma. Os níveis das zonas no mapa também cobrem a Ilha de Zephras (1-12), as Riverglades (35-45) e o Monte Hyjal (60).",
    ["wn_141_codex"] = "Novo - Códice de masmorras: as entradas agora vêm das tabelas do jogo, a maioria das masmorras passa de um ponto aproximado para a entrada real, e a Fortaleza de Krol'dok, o Bastião Boca Negra e o Terraço do Modelador finalmente têm a sua. Chegam as 8 raides: Núcleo Derretido, Covil Asa Negra, Covil da Onyxia, Zul'Gurub, os dois Ahn'Qiraj, e o Cume Hyjal e Barrow Deeps do Forever (abrem em 9 de dezembro). /codex compare mostra no jogo a distância entre cada posição e a entrada do jogo. O Cárcere passa para os níveis 24-32.",
    ["wn_141_dialogue"] = "Corrigido - Diálogo de missão: as dicas das recompensas não cobrem mais o texto da missão nem a outra recompensa. Elas abrem ao lado da janela de diálogo, na altura da recompensa sob o mouse, à direita se a tela tiver espaço, senão à esquerda.",
    ["wn_141_kb"] = "Alterado - /kb agora abre o modo de atalhos rápidos: passe o mouse sobre um botão e aperte uma tecla. Também um botão Atalhos de teclado em Barras de ação.",
})
